class WordDictionary {
  private static class Node {
    Node[] next = new Node[26];
    boolean end;
  }

  private final Node root = new Node();

  public WordDictionary() {}

  public void addWord(String word) {
    Node node = root;
    for (char c : word.toCharArray()) {
      if (node.next[c - 'a'] == null) node.next[c - 'a'] = new Node();
      node = node.next[c - 'a'];
    }
    node.end = true;
  }

  public boolean search(String word) {
    return search(word, 0, root);
  }

  private boolean search(String word, int i, Node node) {
    if (i == word.length()) return node.end;
    char c = word.charAt(i);
    if (c != '.') {
      Node next = node.next[c - 'a'];
      return next != null && search(word, i + 1, next);
    }
    for (Node next : node.next) if (next != null && search(word, i + 1, next)) return true;
    return false;
  }
}
